ALTER TABLE public."squawk_recipient_preferences" ADD CONSTRAINT "squawk_recipient_preferences_email_status_check" CHECK ((email_status = ANY (ARRAY['unknown'::text, 'transactional_only'::text, 'subscribed'::text, 'unsubscribed'::text])));
ALTER TABLE public."squawk_recipient_preferences" ADD CONSTRAINT "squawk_recipient_preferences_sms_status_check" CHECK ((sms_status = ANY (ARRAY['unknown'::text, 'transactional_only'::text, 'subscribed'::text, 'unsubscribed'::text])));
ALTER TABLE public."squawk_templates" ADD CONSTRAINT "squawk_templates_channel_options_check" CHECK (((cardinality(channel_options) > 0) AND (channel_options <@ ARRAY['in_app'::text, 'email'::text, 'sms'::text])));
ALTER TABLE public."squawk_templates" ADD CONSTRAINT "squawk_templates_message_kind_check" CHECK ((message_kind = ANY (ARRAY['message'::text, 'announcement'::text, 'payment_reminder'::text, 'invoice'::text, 'registration_confirmation'::text, 'event_update'::text, 'system'::text])));
ALTER TABLE public."squawk_threads" ADD CONSTRAINT "squawk_threads_context_type_check" CHECK ((context_type = ANY (ARRAY['eig_command'::text, 'hangar'::text, 'cockpit'::text, 'atc'::text, 'event'::text, 'passenger'::text, 'sponsor'::text, 'vendor'::text, 'volunteer'::text, 'crew'::text, 'system'::text, 'direct'::text])));
ALTER TABLE public."squawk_threads" ADD CONSTRAINT "squawk_threads_status_check" CHECK ((status = ANY (ARRAY['open'::text, 'closed'::text, 'archived'::text])));
ALTER TABLE public."team_registrations" ADD CONSTRAINT "team_registrations_amount_charged_check" CHECK ((amount_charged >= (0)::numeric));
ALTER TABLE public."team_registrations" ADD CONSTRAINT "team_registrations_comp_reason_required_check" CHECK (((registration_source <> 'comp'::text) OR ((NULLIF(btrim(comp_reason), ''::text) IS NOT NULL) AND (NULLIF(btrim(comp_approved_by), ''::text) IS NOT NULL) AND (comp_approved_at IS NOT NULL) AND (payment_status = 'complimentary'::text))));
ALTER TABLE public."team_registrations" ADD CONSTRAINT "team_registrations_payment_status_check" CHECK ((payment_status = ANY (ARRAY['pending'::text, 'paid'::text, 'invoiced'::text, 'included'::text, 'complimentary'::text, 'refunded'::text])));
ALTER TABLE public."team_registrations" ADD CONSTRAINT "team_registrations_registered_golfer_count_check" CHECK ((registered_golfer_count >= 0));
ALTER TABLE public."team_registrations" ADD CONSTRAINT "team_registrations_roster_status_check" CHECK ((roster_status = ANY (ARRAY['empty'::text, 'incomplete'::text, 'complete'::text])));
ALTER TABLE public."team_registrations" ADD CONSTRAINT "team_registrations_source_check" CHECK ((registration_source = ANY (ARRAY['direct'::text, 'sponsorship'::text, 'comp'::text, 'admin'::text])));
ALTER TABLE public."team_registrations" ADD CONSTRAINT "team_registrations_sponsorship_link_required_check" CHECK (((registration_source <> 'sponsorship'::text) OR ((sponsor_purchase_id IS NOT NULL) AND (payment_status = 'included'::text))));
